{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance is launched in a subnet named 'levelupvpc-public-1', which implies it likely has auto-assign public IP enabled or is intended to be publicly accessible. Public exposure increases the attack surface for SSH brute-force and other network-based attacks."
    },
    {
      "check_id": "AVD-AWS-0028",
      "title": "Instance metadata service (IMDS) does not require tokens",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "HIGH",
      "explanation": "The instance lacks an `metadata_options` block enforcing IMDSv2 (`http_tokens = \"required\"`). Without this, the Instance Metadata Service can be accessed via unauthenticated requests, potentially allowing attackers to steal IAM credentials if SSRF vulnerabilities exist on the host."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"MyFirstInstnace\" {\n  ami           = lookup(var.AMIS, var.AWS_REGION)\n  instance_type = \"t2.micro\"\n  availability_zone = \"us-east-2a\"\n  key_name      = aws_key_pair.levelup_key.key_name\n  vpc_security_group_ids = [aws_security_group.allow-levelup-ssh.id]\n  subnet_id = aws_subnet.levelupvpc-public-1.id\n\n  # CKV_AWS_88: Disable automatic public IP assignment\n  associate_public_ip_address = false\n\n  # AVD-AWS-0028: Enforce IMDSv2 by requiring HTTP tokens\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n}",
  "fix_summary": "Added `associate_public_ip_address = false` to prevent unintended public exposure of the EC2 instance. Added a `metadata_options` block with `http_tokens = \"required\"` to enforce IMDSv2, mitigating risks associated with unauthenticated access to instance metadata."
}
